import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"隐私选择","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy-choices.md","filePath":"zh-CN/guide/privacy-choices.md","lastUpdated":1793173149000}`),a={name:`zh-CN/guide/privacy-choices.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="隐私选择" tabindex="-1">隐私选择 <a class="header-anchor" href="#隐私选择" aria-label="Permalink to “隐私选择”">​</a></h1><p>Sudoku 是一款以离线为先、数据处理极简的应用。本页说明您有哪些隐私选项，以及如何控制自己的数据。</p><h2 id="您的数据默认留在您的设备上" tabindex="-1">您的数据默认留在您的设备上 <a class="header-anchor" href="#您的数据默认留在您的设备上" aria-label="Permalink to “您的数据默认留在您的设备上”">​</a></h2><ul><li>所有游戏数据——设置、游戏状态、铅笔笔记和统计数据——默认存储在您的设备本地。</li><li>核心玩法无需任何网络访问。</li><li>没有广告，没有数据分析，也没有追踪。</li></ul><h2 id="可选的云功能" tabindex="-1">可选的云功能 <a class="header-anchor" href="#可选的云功能" aria-label="Permalink to “可选的云功能”">​</a></h2><h3 id="icloud-同步" tabindex="-1">iCloud 同步 <a class="header-anchor" href="#icloud-同步" aria-label="Permalink to “iCloud 同步”">​</a></h3><p>如果您选择启用 iCloud 同步：</p><ul><li>数据只会同步到<strong>您个人的 iCloud 账户</strong>——不会同步到我们控制的任何服务器。</li><li>传输和存储过程中的加密由 Apple 的 CloudKit 负责。</li><li>您可以随时关闭此功能：设置 → [你的名字] → iCloud → 使用 iCloud 的 App → 关闭 Sudoku 的开关。</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>如果您选择使用 Game Center：</p><ul><li>排行榜成绩可能会以您的 Game Center 显示名称公开显示。</li><li>成就进度会由 Game Center 记录。</li><li>您可以在设置中退出 Game Center 登录来关闭此功能。</li></ul><h2 id="唯一的非云端网络功能-更多-app" tabindex="-1">唯一的非云端网络功能：“更多 App” <a class="header-anchor" href="#唯一的非云端网络功能-更多-app" aria-label="Permalink to “唯一的非云端网络功能：“更多 App””">​</a></h2><p>唯一的其他网络访问，是设置中可选的 <strong>“更多 App”</strong> 板块，它会获取同系列应用的列表。此功能：</p><ul><li>不发送任何个人数据——仅获取一份应用名称与链接列表。</li><li>完全可以忽略，对游戏体验没有任何影响。</li><li>不会追踪您，也不会存储任何标识符。</li></ul><h2 id="清除您的数据" tabindex="-1">清除您的数据 <a class="header-anchor" href="#清除您的数据" aria-label="Permalink to “清除您的数据”">​</a></h2><p>如需从设备上移除应用的全部数据：</p><ul><li><strong>iPhone/iPad</strong>：删除并重新安装应用</li><li><strong>Mac</strong>：退出 Sudoku，然后删除容器：</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><p>如需一并清除 iCloud 中同步的数据：</p><ol><li>进入 <strong>设置 → [你的名字] → iCloud → 管理账户储存空间</strong></li><li>在应用列表中找到 Sudoku</li><li>点按 <strong>删除数据</strong></li></ol><p>此操作将从 iCloud 中永久删除所有设置、统计数据、游戏存档和每日挑战进度。</p><h2 id="无追踪-无广告" tabindex="-1">无追踪，无广告 <a class="header-anchor" href="#无追踪-无广告" aria-label="Permalink to “无追踪，无广告”">​</a></h2><p>Sudoku 不含任何广告、数据分析、追踪像素，也不含任何第三方数据共享集成。游玩本应用不需要网络访问。</p><h2 id="隐私请求概要" tabindex="-1">隐私请求概要 <a class="header-anchor" href="#隐私请求概要" aria-label="Permalink to “隐私请求概要”">​</a></h2><table tabindex="0"><thead><tr><th>请求</th><th>是否必需？</th><th>作用</th></tr></thead><tbody><tr><td>本地存储</td><td>是（自动）</td><td>将游戏数据存储在设备上</td></tr><tr><td>iCloud 同步</td><td>可选</td><td>通过 CloudKit 在您的设备间同步数据</td></tr><tr><td>Game Center</td><td>可选</td><td>排行榜与成就</td></tr><tr><td>网络（“更多 App”）</td><td>可选</td><td>获取同系列应用列表</td></tr></tbody></table><p>由于我们不收集任何个人数据，也不会将其传输到我们控制的服务器，因此不存在可供访问、删除或迁移的中央数据库。所有数据要么存储在本地，要么由 Apple 的服务（iCloud/Game Center）管理。</p><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to “联系我们”">​</a></h2><p>如对本流程有任何疑问，请在 <code>https://github.com/sudoku-pro/sudoku-site/issues</code> 提交 issue，或发送邮件至 <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a>。</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};